CREATE TABLE public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', phone text not null default '', address text not null default '', landmark text not null default '', online boolean not null default false);
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid references auth.users(id) on delete cascade, role text not null check(role in ('admin','rider')), primary key(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(uid uuid, wanted text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role=wanted) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.products (id text primary key, name text not null, category text not null, unit text not null, price numeric not null check(price>=0), mrp numeric not null check(mrp>=0), image_index integer not null default 0, in_stock boolean not null default true);
GRANT SELECT ON public.products TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON public.products FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY catalog_admin ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.settings (id integer primary key default 1 check(id=1), free_delivery numeric not null default 499, delivery_fee numeric not null default 30, banner_title text not null default 'Fresh from the mandi.', banner_subtitle text not null default 'Your daily essentials, delivered with care.', coupon_code text not null default 'HATA50', coupon_discount numeric not null default 50, coupon_minimum numeric not null default 499);
GRANT SELECT ON public.settings TO anon,authenticated; GRANT UPDATE ON public.settings TO authenticated; GRANT ALL ON public.settings TO service_role;
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY settings_edit ON public.settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders (id uuid primary key default gen_random_uuid(), customer_id uuid not null, rider_id uuid, customer_name text not null, phone text not null, address text not null, landmark text not null default '', slot text not null default 'As soon as possible', payment text not null check(payment in ('COD','UPI')), items jsonb not null, subtotal numeric not null, delivery_fee numeric not null, discount numeric not null default 0, total numeric not null, status text not null default 'Placed' check(status in ('Placed','Confirmed','Picked up','Delivered','Cancelled')), otp text not null default lpad(floor(random()*10000)::text,4,'0'), picked_shops jsonb not null default '[]', created_at timestamptz not null default now());
GRANT SELECT,UPDATE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_read ON public.orders FOR SELECT TO authenticated USING(customer_id=auth.uid() OR rider_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY order_admin ON public.orders FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX orders_customer ON public.orders(customer_id); CREATE INDEX orders_rider ON public.orders(rider_id);
CREATE TABLE public.vendors (id uuid primary key default gen_random_uuid(), name text not null, phone text not null default '', category text not null default 'Groceries');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.vendors TO authenticated; GRANT ALL ON public.vendors TO service_role;
ALTER TABLE public.vendors ENABLE ROW LEVEL SECURITY;
CREATE POLICY vendor_staff ON public.vendors FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.vendor_ledger (id uuid primary key default gen_random_uuid(), vendor_id uuid references public.vendors(id), kind text not null check(kind in ('Purchase','Settlement')), amount numeric not null check(amount>0), note text not null default '', created_at timestamptz not null default now());
GRANT SELECT,INSERT ON public.vendor_ledger TO authenticated; GRANT ALL ON public.vendor_ledger TO service_role;
ALTER TABLE public.vendor_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY ledger_staff ON public.vendor_ledger FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.cod_settlements(id uuid primary key default gen_random_uuid(),rider_id uuid not null, amount numeric not null check(amount>0),created_at timestamptz not null default now());
GRANT SELECT,INSERT ON public.cod_settlements TO authenticated; GRANT ALL ON public.cod_settlements TO service_role;
ALTER TABLE public.cod_settlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY settlement_read ON public.cod_settlements FOR SELECT TO authenticated USING(rider_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY settlement_admin ON public.cod_settlements FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.place_order(details jsonb, cart jsonb, coupon text default '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; product public.products; sum_price numeric:=0; fee numeric; disc numeric:=0; config public.settings; normalized jsonb:='[]'; order_id uuid; qty integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to place an order'; END IF; IF jsonb_array_length(cart)=0 THEN RAISE EXCEPTION 'Cart is empty'; END IF; SELECT * INTO config FROM public.settings WHERE id=1; FOR item IN SELECT * FROM jsonb_array_elements(cart) LOOP qty:=(item->>'quantity')::integer; IF qty<1 OR qty>99 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; SELECT * INTO product FROM public.products WHERE id=item->>'id' AND in_stock FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Product unavailable'; END IF; sum_price:=sum_price+product.price*qty; normalized:=normalized||jsonb_build_array(jsonb_build_object('id',product.id,'name',product.name,'unit',product.unit,'price',product.price,'quantity',qty,'image_index',product.image_index)); END LOOP; fee:=CASE WHEN sum_price>=config.free_delivery THEN 0 ELSE config.delivery_fee END; IF upper(coupon)=config.coupon_code AND sum_price>=config.coupon_minimum THEN disc:=least(config.coupon_discount,sum_price); END IF; IF length(trim(details->>'address'))<5 OR length(trim(details->>'phone'))<>10 OR length(trim(details->>'name'))<2 THEN RAISE EXCEPTION 'Enter your name, 10-digit phone and full address'; END IF; INSERT INTO public.orders(customer_id,customer_name,phone,address,landmark,slot,payment,items,subtotal,delivery_fee,discount,total) VALUES(auth.uid(),details->>'name',details->>'phone',details->>'address',coalesce(details->>'landmark',''),coalesce(details->>'slot','As soon as possible'),details->>'payment',normalized,sum_price,fee,disc,sum_price+fee-disc) RETURNING id INTO order_id; RETURN order_id; END $$;
REVOKE ALL ON FUNCTION public.place_order(jsonb,jsonb,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.place_order(jsonb,jsonb,text) TO authenticated;
CREATE FUNCTION public.rider_update(order_id uuid, next_status text, code text default '', shops jsonb default '[]') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE current_order public.orders; BEGIN SELECT * INTO current_order FROM public.orders WHERE id=order_id FOR UPDATE; IF NOT public.has_role(auth.uid(),'rider') OR current_order.rider_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Not assigned to you'; END IF; IF next_status='Picked up' AND current_order.status='Confirmed' THEN UPDATE public.orders SET status='Picked up',picked_shops=shops WHERE id=order_id; ELSIF next_status='Delivered' AND current_order.status='Picked up' AND code=current_order.otp THEN UPDATE public.orders SET status='Delivered' WHERE id=order_id; ELSE RAISE EXCEPTION 'Invalid status or delivery OTP'; END IF; END $$;
REVOKE ALL ON FUNCTION public.rider_update(uuid,text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.rider_update(uuid,text,text,jsonb) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.orders;
